$('#addForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')||'').trim();if(!title)return;const type=f.get('type');const selected=selectedCatalogTitle;const match=(selected&&items.find(r=>r.id===selected.id))||items.find(r=>normalized(r.title)===normalized(title)&&r.type===type&&String(year(r))===String(f.get('year')||year(r)));if(match){if(match.hidden){update(match.id,{hidden:false});render()}$('#addDialog').close();clearCatalogSelection(true);openDetail(match.id);toast('Esse título já está na sua biblioteca. Histórico preservado.');return}const poster=String(f.get('poster')||'').trim();if(poster&&!safeURL(poster)){toast('Use uma URL de imagem válida.');return}const r={id:selected?.id||'manual-'+crypto.randomUUID(),title,type,year:f.get('year'),runtime:Number(f.get('runtime'))||null,genres:String(f.get('genre')||'').split(',').map(g=>g.trim()).filter(Boolean),synopsis:String(f.get('synopsis')||'').trim(),poster:safeURL(poster)||safeImageURL(selected?.poster)||'',status:'watchlist',collections:[],addedDate:new Date().toISOString()};if(selected){r.tmdb=selected.tmdb;r.imdb=selected.imdb;r.backdrop=selected.backdrop;r.originalTitle=selected.originalTitle;r.synopsisSource=r.synopsis===selected.synopsis?selected.synopsisSource:null;r.synopsisLanguage=selected.synopsisLanguage;r.posterSource=selected.posterSource||selected.synopsisSource}items.push(r);added.push(r);const ok=persist();clearCatalogSelection(true);closeSuggestions();$('#addDialog').close();navigate('watchlist');if(ok)toast('Título adicionado à sua lista.');});
const pad2=n=>String(n).padStart(2,'0');
const isReprint=note=>/Relançamento|Evento|Transmissão|Restaurado/i.test(note||'');
function upcomingAll(){const today=new Date().toISOString().slice(0,10);const rows=new Map();(window.CINE360_DATA.catalog||[]).forEach(r=>{const d=(r.release_date||'').slice(0,10);if(d>=today)rows.set(normalized(r.title)+'|'+r.type,{id:r.id,title:r.title,type:r.type,release_date:d,poster:r.poster||'',backdrop:r.backdrop||'',synopsis:r.synopsis||'',synopsisSource:r.synopsisSource||null,synopsisLanguage:r.synopsisLanguage,tmdb:r.tmdb,genreIds:r.genreIds||[],kind:''})});releases.forEach(([day,type,title,note])=>{if(isReprint(note))return;const d=`2026-10-${pad2(day)}`;if(d<today)return;const tv=type==='stream'&&/Série|Temporada|Anime/.test(note||'');const kindType=tv?'tv':'movie';const key=normalized(title)+'|'+kindType;const catalogHit=[...rows.values()].find(x=>normalized(x.title)===normalized(title));if(catalogHit){catalogHit.kind=type==='stream'?'Streaming':'Cinema';return}if(!rows.has(key))rows.set(key,{id:'cal-'+normalized(title).replace(/[^a-z0-9]+/g,'-'),title,type:kindType,release_date:d,poster:'',backdrop:'',synopsis:'',genreIds:[],kind:type==='stream'?'Streaming':'Cinema',note:note||''})});return [...rows.values()].sort((a,b)=>a.release_date.localeCompare(b.release_date)||a.title.localeCompare(b.title,'pt-BR'))}
function greetingLine(){const h=Number(new Intl.DateTimeFormat('en-US',{hour:'numeric',hour12:false,timeZone:'America/Sao_Paulo'}).formatToParts(new Date()).find(p=>p.type==='hour').value)%24;if(h>=5&&h<=11)return 'Bom dia, Enzo!';if(h>=12&&h<=17)return 'Boa tarde, Enzo!';if(h>=18)return 'Boa noite, Enzo!';return 'Madrugando, Enzo?'}
function upcomingRows(){return upcomingAll()}
let heroIndex=0,heroElapsed=0;const HERO_MS=20000;
function heroSlide(){const list=items.filter(r=>!r.hidden&&r.rating&&(r.status==='watched'||r.status==='history')).sort((a,b)=>(b.addedDate||'').localeCompare(a.addedDate||'')||sofaPos(a)-sofaPos(b));if(!list.length)return '<section class="hero hero-carousel"><div class="hero-content"><span class="hero-badge">ÚLTIMOS ASSISTIDOS</span><h2>Avalie um título para vê-lo aqui.</h2><p class="hero-synopsis">Os títulos que você assistiu e avaliou aparecem neste destaque.</p></div></section>';const i=((heroIndex%list.length)+list.length)%list.length;const r=list[i];const img=safeImageURL(r.backdrop||r.poster);const syn=r.synopsis||'Sinopse não disponível no catálogo. Você pode cadastrá-la em “Editar detalhes”.';const plats=(Array.isArray(r.streaming)?r.streaming:[]).filter(Boolean);const platHTML=plats.length?plats.map(pl=>{const slug=normalized(pl).replace(/[^a-z0-9]+/g,'-');return `<span class="platform-chip"><img src="assets/platforms/${slug}.svg" alt="${esc(pl)}" data-platform-logo data-name="${esc(pl)}"></span>`}).join(''):'<span class="platform-empty">Plataforma não informada</span>';return `<section class="hero hero-carousel" aria-roledescription="carrossel" aria-label="Últimos títulos assistidos e avaliados">${img?`<img class="hero-image" src="${esc(img)}" alt="" referrerpolicy="no-referrer">`:'<div class="hero-image hero-noimg" aria-hidden="true"></div>'}<div class="hero-content"><span class="hero-badge">${icon('star')} ÚLTIMOS ASSISTIDOS · ${r.type==='tv'?'SÉRIE':'FILME'}</span><h2>${esc(r.title)}</h2><div class="hero-meta"><span>${esc(year(r))}</span><span>·</span><span>${esc(genres(r)[0]||(r.type==='tv'?'Série':'Filme'))}</span></div><div class="hero-rating">${stars(r.rating)}<b>${Number(r.rating).toFixed(1)}</b><span>sua nota</span></div><p class="hero-synopsis">${esc(syn)}</p><button class="primary" data-open="${esc(r.id)}">Abrir título ${icon('arrow')}</button></div><div class="hero-nav"><button type="button" data-hero-step="-1" aria-label="Título anterior">←</button><span class="hero-counter" aria-live="polite">${i+1} / ${list.length}</span><button type="button" data-hero-step="1" aria-label="Próximo título">→</button></div><div class="hero-progress" aria-hidden="true"><span id="heroBar" style="width:${(heroElapsed/HERO_MS*100).toFixed(2)}%"></span></div></section>`}
let heroLast=performance.now();
function heroTick(now){const dt=Math.min(100,now-heroLast);heroLast=now;if(view==='home'&&!search&&!document.querySelector('dialog[open]')&&!document.hidden){heroElapsed+=dt;if(heroElapsed>=HERO_MS){heroIndex++;heroElapsed=0;render()}else{const bar=$('#heroBar');if(bar)bar.style.width=(heroElapsed/HERO_MS*100)+'%'}}requestAnimationFrame(heroTick)}
