function upcoming(){const rows=upcomingRows();const monthLabel=k=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(k+'-15T12:00:00'));const section=(type,label)=>{const list=rows.filter(r=>r.type===type);const groups=new Map();list.forEach(r=>{const k=r.release_date.slice(0,7);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r)});return `<section class="section up-section"><h2 class="up-type">${label}<span>${list.length} ${list.length===1?'título':'títulos'}</span></h2>${list.length?[...groups].map(([k,arr])=>`<div class="up-month"><h3>${esc(monthLabel(k))}</h3><div class="up-grid">${arr.map(upcomingCard).join('')}</div></div>`).join(''):'<p class="muted">Nenhum lançamento com foto neste catálogo ainda.</p>'}</section>`};return `${heading('Próximos lançamentos','Filmes e séries que chegam ao cinema e ao streaming, com foto e data. Adicione à sua lista de desejos.','FIQUE DE OLHO')}${section('movie','Filmes')}${section('tv','Séries')}<p class="source-note">Lançamentos com foto vindos do catálogo. A marcação Cinema ou Streaming aparece quando a data também consta na agenda de outubro (Showmetech, Cenanauta e Omelete).</p>`}
function addWish(id){const src=upcomingAll().find(r=>r.id===id);if(!src)return;if(items.some(x=>x.id===id&&!x.hidden)){toast('Esse título já está na sua biblioteca.');return}if(items.some(x=>x.id===id)){update(id,{hidden:false,status:'watchlist'})}else{const r={id:src.id,title:src.title,type:src.type,release_date:src.release_date,runtime:null,genres:(src.genreIds||[]).map(g=>catalogGenres[g]).filter(Boolean),synopsis:src.synopsis||'',synopsisSource:src.synopsisSource||null,synopsisLanguage:src.synopsisLanguage,poster:safeURL(src.poster)||'',backdrop:safeURL(src.backdrop)||'',tmdb:src.tmdb,status:'watchlist',collections:[],addedDate:new Date().toISOString()};items.push(r);added.push(r);persist()}render();toast('Adicionado à sua lista de desejos.')}
