function burst(x,y,symbols){for(let i=0;i<10;i++){const el=document.createElement('span');el.className='burst-particle';el.textContent=symbols[i%symbols.length];const a=Math.random()*Math.PI*2,d=44+Math.random()*56;el.style.left=x+'px';el.style.top=y+'px';el.style.setProperty('--dx',Math.cos(a)*d+'px');el.style.setProperty('--dy',(Math.sin(a)*d-24)+'px');document.body.appendChild(el);setTimeout(()=>el.remove(),900)}}
